import HeroBasic from '../components/HeroBasic'
import Card from '../components/Card'
import List from '../components/List'
import InfoBox from '../components/InfoBox'
import { useDocs } from 'data/data'

function normalizeRegionValue(regionLabel) {
    return regionLabel.replace('Region ', '').trim().toUpperCase()
}

function countDocsForRegion(docs, regionLabel) {
    let targetRegion = normalizeRegionValue(regionLabel)

    return docs.reduce((count, doc) => {
        let docRegion = doc.region == null ? '' : doc.region.toString().trim().toUpperCase()

        if (docRegion === targetRegion) {
            return count + 1
        }

        return count
    }, 0)
}

function BuildInfoGrid({ docs }) {
    var infoList = [
        {
            header: "Region 1",
            text: "This section focuses on enforcement actions and compliance inspections related to air quality and hazardous waste management in various facilities across New England.",
        },
        {
            header: "Region 2",
            text: "This section focuses on enforcement actions and compliance evaluations related to hazardous waste and air quality regulations in Region 2, particularly in Puerto Rico and New York."
        },
        {
            header: "Region 3",
            text: "This section focuses on compliance inspections and hazardous waste management in various industries across Region 3, particularly under the Clean Water Act and Resource Conservation and Recovery Act."
        },
        {
            header: "Region 4",
            text: ""
        },
        {
            header: "Region 5",
            text: ""
        },
        {
            header: "Region 6",
            text: ""
        },
        {
            header: "Region 7",
            text: "This section focuses on compliance evaluations and inspections of hazardous waste and air quality regulations across various industries in Region 7, including Iowa, Missouri, Nebraska, and Kansas."
        },
        {
            header: "Region 8",
            text: ""
        },
        {
            header: "Region 9",
            text: ""
        },

        {
            header: "Region 10",
            text: "This section focuses on environmental compliance and enforcement actions primarily related to water and air quality regulations in Alaska and the Pacific Northwest."
        },
        {
            header: "Region HQ",
            text: ""
        },
    ] 

    var infoCards = infoList.map((a, index) => {
        let regionCount = countDocsForRegion(docs, a.header)
        let regionValue = a.header.replace('Region ', '')

        return <InfoBox
            key={index}
            href={`/portal?epaRegion=${encodeURIComponent(regionValue)}`}
            header={
                <span style={{display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: '0.75rem'}}>
                    <span>{a.header}</span>
                    <span style={{fontSize: '0.75rem', fontWeight: 700, padding: '0.2rem 0.55rem', borderRadius: '999px', background: '#E7F0FA', color: '#24507A'}}>
                        {regionCount.toLocaleString()} docs
                    </span>
                </span>
            }
        >
            {a.text ? <p>{a.text}</p> : <List items={a.items} />}
        </InfoBox>
    })

    return <div className="grid">{infoCards}</div>
}

function EPARegions() {
    const { allDocs, isLoading } = useDocs()

    var heroTitle = "EPA Regions"
    var heroSubtitle = "All EPA Regions part of the Enforcement Transparency Project."

    var infoGrid = BuildInfoGrid({ docs: isLoading ? [] : allDocs })
    return (
        <div>
            <HeroBasic title={heroTitle} subtitle={heroSubtitle} />
            <Card header="">
                {infoGrid}
            </Card>
        </div>
    )
}

export default EPARegions
