import { useDocs } from 'data/data'

import Button from 'features/portal/Button'

function Header() {
    const { docs, filter, isLoading } = useDocs()

    let documentCountBadge = null
    let statuteCountBadges = null

    if (isLoading === false) {
        documentCountBadge = <span className="results-count-badge">{docs.length.toLocaleString()} documents</span>

        let statutes = []
        for (let i = 0; i < filter.statute.length; i++) {
            let statute = {}
            statute.name = filter.statute[i]

            statute.count = docs.reduce((arr, cur) => {
                if (cur.statute == statute.name) {
                    return arr+1
                }
                return arr
            }, 0)

            statutes.push(statute)
        }

        statuteCountBadges = statutes.map((a) => {
            if (a.count == 0)
                return null
            return <span className={"badge " + a.name.toLowerCase()} key={a.name}>{a.count.toLocaleString()} {a.name}</span>
        })

    }

    return (
        <>
            <div>
                <div className="dashboard-kicker">
                    Transparency Records
                </div>

                <div className="results-title">
                    <i className="ti ti-files"></i>
                    <span>Document Results</span>
                    { documentCountBadge }
                    { statuteCountBadges }
                </div>
            </div>

            <div className="results-tools">
                <Button isPrimary={true}>Download Data</Button>
                <Button>Insights</Button>
                <Button>Export CSV</Button>
            </div>
        </>
    )
}

export default Header;