import HeroBasic from '../components/HeroBasic.js';
import Card from '../components/Card.js';
import InfoBox from '../components/InfoBox.js';
import Button from '../components/Button.js';

function BuildInfoBoxes() {
        var infoBoxData = [
                {
                        title: "Search Portal",
                        body: "Search inspection reports, notices of violation, and enforcement records.",
                        button: {
                                text: "Open Portal",
                                href: "/portal"
                        }
                },
                {
                        title: "Why This Matters",
                        body: "Learn why environmental transparency and enforcement oversight matter.",
                        button: {
                                text: "Read More",
                                href: "/why-this-matters"
                        }
                },
                {
                        title: "Project Background",
                        body: "Learn how the FOIA effort and data collaboration developed.",
                        button: {
                                text: "Project History",
                                href: "/project-background"
                        }
                }
        ]

        var infoBoxes = infoBoxData.map((a, index) => 
                <InfoBox key={index} header={a.title}>
                        <p>{a.body}</p>
                        <Button href={a.button.href}>
                                {a.button.text}
                        </Button>
                </InfoBox>        
        )

        return <div className='grid'>{infoBoxes}</div>
}

function Home() {
        var heroTitle = "Enforcement Transparency Project";
        var heroSubtitle = "A public-interest transparency initiative exposing environmental enforcement records obtained through FOIA."

        var cardHeader = "About the Project"
        var infoBoxes = BuildInfoBoxes()

        return (
                <div className="Home">
                        <HeroBasic title={heroTitle} subtitle={heroSubtitle}/>
                        <Card header={cardHeader}>
                                <p>The Enforcement Transparency Project exposes previously hidden government documents, primarily from EPA, for use in tracking enforcement under the Clean Air Act, Clean Water Act, Resource Conservation and Recovery Act (RCRA), and other statutes.</p>
                                <p>EPA has never fully digitized or published many of these records. PEER obtained these documents through Freedom of Information Act requests and is making them searchable through the Search Portal. </p>
                                {infoBoxes}
                        </Card>
                </div>
        );
}

export default Home;
